define('mod_lamslesson/validate', ['exports', 'core/config', 'core/str'], function(exports, Config, Str) {
    'use strict';

    Config = Config && Config.default ? Config.default : Config;

    var SELECTORS = {
        serverUrl: '#id_s__lamslesson_serverurl',
        serverId: '#id_s__lamslesson_serverid',
        serverKey: '#id_s__lamslesson_serverkey',
        offsetButton: '#offsetbtn',
        validateButton: '#validatebtn'
    };

    var getValue = function(selector) {
        var field = document.querySelector(selector);
        return field ? field.value.trim() : '';
    };

    var createQuery = function() {
        var params = new URLSearchParams();
        params.append('u', getValue(SELECTORS.serverUrl));
        params.append('i', getValue(SELECTORS.serverId));
        params.append('k', getValue(SELECTORS.serverKey));
        return params;
    };

    var post = async function(endpoint, params) {
        var response = await fetch(Config.wwwroot + '/mod/lamslesson/' + endpoint, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8'
            },
            body: params.toString()
        });

        var result = await response.text();
        if (!response.ok) {
            throw new Error(result);
        }

        return result;
    };

    var setButtonBusy = function(button, busy) {
        if (!button) {
            return;
        }

        if (busy) {
            button.dataset.originalText = button.textContent;
            button.textContent = button.textContent + '...';
            button.classList.add('disabled');
            button.setAttribute('aria-disabled', 'true');
        } else {
            if (button.dataset.originalText) {
                button.textContent = button.dataset.originalText;
            }
            button.classList.remove('disabled');
            button.removeAttribute('aria-disabled');
        }
    };

    var validateFields = async function() {
        var strings = await Promise.all([
            Str.get_string('required', 'core'),
            Str.get_string('invalidserverurl', 'mod_lamslesson')
        ]);
        var required = strings[0];
        var invalidUrl = strings[1];

        var serverUrl = getValue(SELECTORS.serverUrl);
        var serverId = getValue(SELECTORS.serverId);
        var serverKey = getValue(SELECTORS.serverKey);

        var errors = '';
        var firstInvalidField = null;
        var serverUrlField = document.querySelector(SELECTORS.serverUrl);
        var serverIdField = document.querySelector(SELECTORS.serverId);
        var serverKeyField = document.querySelector(SELECTORS.serverKey);

        if (serverUrl.length === 0) {
            errors += '* server_url ' + required + '\n';
            firstInvalidField = serverUrlField;
        } else if (!/^https?:\/\//i.test(serverUrl)) {
            errors += '* server_url ' + invalidUrl + '\n';
            firstInvalidField = serverUrlField;
        }

        if (serverId.length === 0) {
            errors += '* server_id ' + required + '\n';
            firstInvalidField = firstInvalidField || serverIdField;
        }

        if (serverKey.length === 0) {
            errors += '* server_key ' + required + '\n';
            firstInvalidField = firstInvalidField || serverKeyField;
        }

        if (errors.length > 0) {
            window.alert(errors.trim());
            if (firstInvalidField) {
                firstInvalidField.focus();
            }
            return false;
        }

        return true;
    };

    var verify = async function() {
        var button = document.querySelector(SELECTORS.validateButton);
        setButtonBusy(button, true);
        try {
            var result = await post('verify.php', createQuery());
            if (result.trim() !== '1') {
                window.alert(result);
            }
        } catch (error) {
            window.alert(error.message);
        } finally {
            setButtonBusy(button, false);
        }
    };

    var validate = async function() {
        if (await validateFields()) {
            await verify();
        }
    };

    var calculateOffset = async function() {
        var button = document.querySelector(SELECTORS.offsetButton);
        setButtonBusy(button, true);
        try {
            var result = await post('offset.php', createQuery());
            if (result.trim() !== '1') {
                window.alert(result);
            }
        } catch (error) {
            window.alert(error.message);
        } finally {
            setButtonBusy(button, false);
        }
    };

    var init = function() {
        var offsetButton = document.querySelector(SELECTORS.offsetButton);
        if (offsetButton) {
            offsetButton.addEventListener('click', function(event) {
                event.preventDefault();
                calculateOffset();
            });
        }

        var validateButton = document.querySelector(SELECTORS.validateButton);
        if (validateButton) {
            validateButton.addEventListener('click', function(event) {
                event.preventDefault();
                validate();
            });
        }
    };

    exports.init = init;
});
